import{_ as i,h as t,i as e,c as o,v as l,p as s,x as r,m as p,e as d,S as h}from"./chunks/framework.Dvtg8yj2.js";const N=JSON.parse('{"title":"第三代 MGX：无缆托盘与可热插拔交换","description":"","frontmatter":{"title":"第三代 MGX：无缆托盘与可热插拔交换","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/mgx-nvl72-tray.md","filePath":"llm/mgx-nvl72-tray.md","lastUpdated":1788454257000}'),A={name:"llm/mgx-nvl72-tray.md"};function E(u,a,B,c,P,m){const n=t("Mermaid");return e(),o("div",null,[a[1]||(a[1]=l('<h1 id="第三代-mgx-无缆托盘与可热插拔交换" tabindex="-1">第三代 MGX：无缆托盘与可热插拔交换 <a class="header-anchor" href="#第三代-mgx-无缆托盘与可热插拔交换" aria-label="Permalink to &quot;第三代 MGX：无缆托盘与可热插拔交换&quot;">​</a></h1><div class="epigraph"><p>机柜要当一块加速器来用，首先得能当一块机器来修：托盘无缆盲插，交换托盘可热插，维护时作业不必整柜下电。</p><footer>—— NVIDIA 对第三代 MGX 与 Vera Rubin NVL72 的公开机械叙事：cable-free、hose-free、fanless，NVLink 交换托盘可在机柜继续运行时更换</footer></div><p><a href="/llm/rack-as-accelerator">机柜作为一块逻辑加速器</a> 讲的是编程模型。本篇讲这块加速器怎么被装进 19 英寸机柜：第三代 NVIDIA MGX。Vera Rubin NVL72 公开写成建立在第三代 MGX 机柜上，18 个计算托盘加 9 个 NVLink 交换托盘，72 个 Rubin GPU 与 36 个 Vera CPU，ConnectX-9 与 BlueField-4 也在托盘里。相对 Blackwell 一代，公开重点从「把 72 卡连上」转到「无缆模块化与可服务性」。NVIDIA 称 Vera Rubin NVL72 已进入量产、按计划在 2026 下半年出货。机械与 RAS 只引用官方已经写出的结构，不编造未公开的背板针数或铜缆眼图。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>第一代 NVL72 已经证明：机柜级 NVLink 域能当一块大加速器。现场立刻暴露另一类故障——不是算法，是电缆。计算托盘内部的 PCIe、管理、网络线，每一根都是装配工时和接触不良的来源。公开对照里，上一代计算托盘组装大约要两小时量级（另有材料写成约 100 分钟）；在十万 GPU 工厂里，这变成上架速度与一次插错的统计事件。风扇与托盘内软管同样是泄漏和机械疲劳点。交换托盘若必须整柜下电才能换，则「一块逻辑加速器」的爆炸半径是 72 卡的维护窗口，而不是一张网卡的热插。</p><p>第三代 MGX 要回答的问题是：在单宽 19 英寸、全液冷、铜脊的约束下，能不能把计算托盘做成盲插模块，把 NVLink 交换做成可维护而不中断机柜。这与<a href="/llm/rubin-liquid-power-smoothing">温水液冷和功率平滑</a> 是同一套机柜的另外两面。</p><h3 id="「无缆」指托盘内-不是机柜没有铜" tabindex="-1">「无缆」指托盘内，不是机柜没有铜 <a class="header-anchor" href="#「无缆」指托盘内-不是机柜没有铜" aria-label="Permalink to &quot;「无缆」指托盘内，不是机柜没有铜&quot;">​</a></h3><p>官方动画与博文把计算托盘写成 PCB 中板 + 盲插，托盘内取消大量手工 PCIe / 网络 / 管理线，也取消托盘内软管与风扇（hose-free、fanless）。机柜背部仍有 NVLink 铜脊：公开描述是最多四组预集成铜缆匣，容纳数以千计的铜缆（NVL72 文中写过约 5000 根、总长两英里量级）。「无缆托盘」不是「无线机柜」。运维手册若写成「机柜里没有任何铜」，会在打开后门时当场破产。MGX 还有 ETL 变体：脊可以是 Spectrum-X 以太网或 Groq LPU 的芯片直连，与 NVL 铜脊同机械外形。</p><p><span class="marginnote">NVIDIA 给出托盘组装从约两小时降到约五分钟、最高约 18–20 倍装服务速度的对照。那是装配工时，不是模型吞吐。不要把 20 倍写进 tokens/s 表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按官方托盘清单来排。每个计算托盘含两颗 Vera Rubin 超级芯片，经 PCB 中板连到前部模块化托架：公开写法是八块 ConnectX-9 SuperNIC 加一块 BlueField-4 DPU。托盘插入机柜时盲配到脊与液冷回路；对外液冷是成对的进出水，而不是托盘内一丛软管。NVLink 6 交换托盘提供机柜级全互连，公开规格包括每 GPU 约 3.6 TB/s、机柜约 260 TB/s 的 scale-up 带宽——这是互连规格，不是单核扫 HBM 的屋顶线。</p><p>可服务性是一等功能。NVLink 交换托盘支持维护模式、在机柜继续运行时更换、部分托盘缺失时仍能运行、动态把流量绕开下线的交换、以及在役软件更新。计算托盘、交换托盘、电源与冷却被写成模块化、可热插、可现场替换，而不必排空整柜或中断正在跑的作业——这是目标语义，具体哪些部件允许带电拔插以硬件用户指南为准。硅级 RAS：Rubin GPU 的健康检查引擎、Vera CPU 的在系统测试与 SOCAMM 内存模块，用来缩短定位和换件时间。</p>',12)),(e(),s(h,null,{default:r(()=>[d(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TB%0A%20%20subgraph%20RACK%5B%22%E7%AC%AC%E4%B8%89%E4%BB%A3%20MGX%20%E5%8D%95%E5%AE%BD%E6%9C%BA%E6%9F%9C%22%5D%0A%20%20%20%20C1%5B%22%E8%AE%A1%E7%AE%97%E6%89%98%E7%9B%98%20%E7%9B%B2%E6%8F%92%22%5D%0A%20%20%20%20C18%5B%22%E2%80%A6%2018%20%E6%89%98%E7%9B%98%22%5D%0A%20%20%20%20S1%5B%22NVLink%20%E4%BA%A4%E6%8D%A2%E6%89%98%E7%9B%98%22%5D%0A%20%20%20%20S9%5B%22%E2%80%A6%209%20%E6%89%98%E7%9B%98%22%5D%0A%20%20%20%20SPINE%5B%22%E9%93%9C%E8%84%8A%20%2F%20%E9%A2%84%E9%9B%86%E6%88%90%E7%BC%86%E5%8C%A3%22%5D%0A%20%20%20%20C1%20---%20SPINE%0A%20%20%20%20C18%20---%20SPINE%0A%20%20%20%20S1%20---%20SPINE%0A%20%20%20%20S9%20---%20SPINE%0A%20%20end%0A%20%20S1%20-.-%3E%7C%22%E7%BB%B4%E6%8A%A4%E6%A8%A1%E5%BC%8F%20%C2%B7%20%E7%83%AD%E6%8F%92%22%7C%20OPS%5B%22%E6%9C%BA%E6%9F%9C%E7%BB%A7%E7%BB%AD%E8%B7%91%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h3 id="从「72-卡域」到「可降级的-72-卡域」" tabindex="-1">从「72 卡域」到「可降级的 72 卡域」 <a class="header-anchor" href="#从「72-卡域」到「可降级的-72-卡域」" aria-label="Permalink to &quot;从「72 卡域」到「可降级的 72 卡域」&quot;">​</a></h3><p>上一代逻辑是：交换托盘是域的脊，坏一块就影响整域带宽。第三代公开加上控制面韧性：部分填充、绕路、在役更新。软件必须配合——调度器要理解「本柜仍在域内、但带宽降级」，而不是在 NCCL 超时后把整柜踢出集群再手工上架。这与把机柜当 9 台 8 卡服务器热拔 GPU 的旧 runbook 不兼容。Kubernetes 设备插件应暴露 NVL 域与托盘健康，而不是只暴露 GPU UUID。</p><p>单宽 19 英寸还改变物流：官方强调相对以往更易运输与部署，整柜重量约 4000 磅量级、约 130 万个零件、近 1300 颗芯片。这些数字说明它是设施级资产，不是「多插几张 PCIe 卡」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>无缆托盘变快、变可靠，是因为接触件从「人工线束」变成「中板连接器」。连接器的寿命与插拔次数是机械设计对象；线束的误插是人为随机过程。风扇取消后，托盘内不再有转动件，热路径全部交给液冷冷板，这与 100% 液冷、无风扇系统的宣称一致。交换热插能成立，是因为 NVLink 交换被做成可绕过的脊：控制面把某托盘标成维护，数据面改路由，作业看到的是带宽与路径变化，而不是 PCI 设备突然消失导致的进程崩溃——前提是驱动与 NCCL 真的实现了这条路径。官方写的是架构能力；集群软件是否接上，是部署问题。</p><p>对 LLM 服务，这意味着维护窗口可以按托盘而不是按「72 卡一台机器」来写。训练长作业更吃这个：检查点间隔以小时计时，整柜下电的代价是重算。推理多副本可以在降级带宽下继续服务，只要路由不把延迟敏感的 TP 组拆到已经稀疏的链路上。</p><p><span class="marginnote">计算托盘前部的八块 ConnectX-9 加一块 BlueField-4，说明 scale-out 与基础设施卸载是托盘级配置，不是机柜外再挂一台。具体每 GPU 对应几张网卡，以硬件指南为准，不要用公开示意图去反推未写出的配比。</span></p><h3 id="mgx-是开放机柜-不是只有-nvl72" tabindex="-1">MGX 是开放机柜，不是只有 NVL72 <a class="header-anchor" href="#mgx-是开放机柜-不是只有-nvl72" aria-label="Permalink to &quot;MGX 是开放机柜，不是只有 NVL72&quot;">​</a></h3><p>NVIDIA 把 MGX 设计贡献给 OCP，并称有 80 多家生态伙伴共用电源、冷却与机械包络。同一代还有 Vera CPU 机柜、BlueField-4 STX 存储机柜、Spectrum-6 SPX 网络机柜、Groq 3 LPX 推理机柜，都走第三代 MGX。对软件，这意味着「托盘盲插、液冷、单宽」是工厂标准件；对算法工程师，这意味着不要为 NVL72 发明一种无法在 MGX 伙伴机柜上落地的特殊背板假设。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要把「热插交换托盘」理解成可以任意时刻拔计算托盘而不丢作业——计算托盘上有 GPU 与正在用的 HBM。不要假设部分填充时 72 路 TP 仍然成立：域变稀疏后应降并行度或迁作业。不要把未公开的连接器寿命、未发布的盲插次数写进验收条款。GB200 / GB300 的托盘线束经验不能直接当 Rubin 的工时，官方已经改掉机械。</p><p>爆炸半径仍然是机柜级：脊或冷却歧管故障不是换一张卡能结束的。热插降低的是交换与部分模块的维修代价，不是把 NVL72 变成刀片服务器。</p><p><span class="marginnote">出处：NVIDIA Vera Rubin NVL72 数据表与 POD / 平台技术博文中的第三代 MGX、18+9 托盘、无缆/无管/无风扇、交换热插与 20 倍组装对照。带宽只用已公布的 NVLink 6 机柜级数字。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>第三代 MGX 把 NVL72 从「能连」推进到「能修」：托盘无缆盲插，交换可热插、可降级运行。</li><li>无缆指托盘内 PCB 中板；机柜脊仍是预集成铜缆匣。</li><li>公开结构仍是 18 计算托盘 + 9 交换托盘，托盘上集成 ConnectX-9 与 BlueField-4。</li><li>调度必须理解维护模式与部分填充，不能在降级域上继续原 TP 度。</li><li>同一机械包络服务多种 MGX 机柜，不独属于 NVL72。</li><li>出处：NVIDIA MGX / Vera Rubin 公开硬件描述。</li></ul>',15))])}const C=i(A,[["render",E]]);export{N as __pageData,C as default};
